use std::fs
use std::strings

struct Tree {
    keys: Vec<int>,
    lefts: Vec<int>,
    rights: Vec<int>,
    root: int,
}

fn height_of(t: Tree) -> int {
    if t.root < 0 { return 0 }
    let mut best = 0
    let mut level = [t.root]
    while level.len() > 0 {
        best += 1
        let mut next: Vec<int> = []
        for n in level {
            if t.lefts[n as usize] >= 0 { next.push(t.lefts[n as usize]) }
            if t.rights[n as usize] >= 0 { next.push(t.rights[n as usize]) }
        }
        level = next
    }
    best
}

fn inorder_of(t: Tree) -> string {
    let mut out: Vec<string> = []
    let mut stack: Vec<int> = []
    let mut cur = t.root
    while cur >= 0 || stack.len() > 0 {
        while cur >= 0 {
            stack.push(cur)
            cur = t.lefts[cur as usize]
        }
        let n = stack.pop() ?? -1
        out.push("${t.keys[n as usize]}")
        cur = t.rights[n as usize]
    }
    out.join(" ")
}

fn main() {
    let text = fs::read_to_string("/dev/stdin") ?? ""
    let mut t = Tree { keys: [], lefts: [], rights: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = strings::split_whitespace(line)
        if parts.len() == 0 { continue }
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse() ?? 0
            let mut cur = t.root
            let mut parent = -1
            let mut went_left = false
            let mut found = false
            while cur >= 0 {
                let k = t.keys[cur as usize]
                if k == x { found = true; break }
                parent = cur
                if x < k {
                    went_left = true
                    cur = t.lefts[cur as usize]
                } else {
                    went_left = false
                    cur = t.rights[cur as usize]
                }
            }
            if found {
                println("dup")
            } else {
                let id = t.keys.len() as int
                t.keys.push(x)
                t.lefts.push(-1)
                t.rights.push(-1)
                if parent < 0 {
                    t.root = id
                } else if went_left {
                    t.lefts[parent as usize] = id
                } else {
                    t.rights[parent as usize] = id
                }
                println("ok")
            }
        } else if cmd == "contains" {
            let x: int = parts[1].parse() ?? 0
            let mut cur = t.root
            let mut found = false
            while cur >= 0 {
                let k = t.keys[cur as usize]
                if k == x { found = true; break }
                if x < k { cur = t.lefts[cur as usize] } else { cur = t.rights[cur as usize] }
            }
            if found { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse() ?? 0
            let mut cur = t.root
            let mut parent = -1
            let mut went_left = false
            let mut found = false
            while cur >= 0 {
                let k = t.keys[cur as usize]
                if k == x { found = true; break }
                parent = cur
                if x < k {
                    went_left = true
                    cur = t.lefts[cur as usize]
                } else {
                    went_left = false
                    cur = t.rights[cur as usize]
                }
            }
            if !found {
                println("missing")
            } else {
                let l = t.lefts[cur as usize]
                let r = t.rights[cur as usize]
                if l >= 0 && r >= 0 {
                    let mut sp = cur
                    let mut s = r
                    let mut s_left = false
                    while t.lefts[s as usize] >= 0 {
                        sp = s
                        s_left = true
                        s = t.lefts[s as usize]
                    }
                    t.keys[cur as usize] = t.keys[s as usize]
                    let sr = t.rights[s as usize]
                    if s_left {
                        t.lefts[sp as usize] = sr
                    } else {
                        t.rights[sp as usize] = sr
                    }
                } else {
                    let child = if l >= 0 { l } else { r }
                    if parent < 0 {
                        t.root = child
                    } else if went_left {
                        t.lefts[parent as usize] = child
                    } else {
                        t.rights[parent as usize] = child
                    }
                }
                println("ok")
            }
        } else if cmd == "inorder" {
            if t.root < 0 { println("<empty>") } else { println(inorder_of(t)) }
        } else if cmd == "height" {
            println("${height_of(t)}")
        } else if cmd == "min" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut cur = t.root
                while t.lefts[cur as usize] >= 0 { cur = t.lefts[cur as usize] }
                println("${t.keys[cur as usize]}")
            }
        } else if cmd == "max" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut cur = t.root
                while t.rights[cur as usize] >= 0 { cur = t.rights[cur as usize] }
                println("${t.keys[cur as usize]}")
            }
        }
    }
}

